Here is the commit message:
rxrpc: Fix error handling in rxgk_extract_token()

Fix a missing bit of error handling in rxgk_extract_token(): in the event
that rxgk_decrypt_skb() returns -ENOMEM, it should just return that rather
than continuing on (for anything else, it generates an abort).

Fixes: 64863f4ca494 ("rxrpc: Fix unhandled errors in rxgk_verify_packet_integrity()")
Closes: https://sashiko.dev/#/patchset/20260422161438.2593376-4-dhowells@redhat.com
Signed-off-by: David Howells <dhowells@redhat.com>
cc: Marc Dionne <marc.dionne@auristor.com>
cc: Jeffrey Altman <jaltman@auristor.com>
cc: Simon Horman <horms@kernel.org>
cc: linux-afs@lists.infradead.org
cc: stable@kernel.org
Link: https://patch.msgid.link/20260423200909.3049438-4-dhowells@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In rxgk_extract_token(), when rxgk_decrypt_skb() returns -ENOMEM, the code did not return the error but instead fell through to subsequent processing (default_decode_ticket), leading to incorrect behavior or corruption due to incomplete token extraction.

Here is the patch:
  */
 int rxgk_extract_token(struct rxrpc_connection *conn, struct sk_buff *skb,
 		       unsigned int token_offset, unsigned int token_len,
 		       struct key **_key)
 {
 	const struct krb5_enctype *krb5;
 	const struct krb5_buffer *server_secret;
 	struct crypto_aead *token_enc = NULL;
 	struct key *server_key;
 	unsigned int ticket_offset, ticket_len;
 	u32 kvno, enctype;
 	int ret, ec = 0;

 	struct {
 		__be32 kvno;
 		__be32 enctype;
 		__be32 token_len;
 	} container;

 	if (token_len < sizeof(container))
 		goto short_packet;

 	/* Decode the RXGK_TokenContainer object.  This tells us which server
 	 * key we should be using.  We can then fetch the key, get the secret
 	 * and set up the crypto to extract the token.
 	 */
 	if (skb_copy_bits(skb, token_offset, &container, sizeof(container)) < 0)
 		goto short_packet;

 	kvno		= ntohl(container.kvno);
 	enctype		= ntohl(container.enctype);
 	ticket_len	= ntohl(container.token_len);
 	ticket_offset	= token_offset + sizeof(container);

 	if (ticket_len > xdr_round_down(token_len - sizeof(container)))
 		goto short_packet;

 	_debug("KVNO %u", kvno);
 	_debug("ENC  %u", enctype);
 	_debug("TLEN %u", ticket_len);

 	server_key = rxrpc_look_up_server_security(conn, skb, kvno, enctype);
 	if (IS_ERR(server_key))
 		goto cant_get_server_key;

 	down_read(&server_key->sem);
 	server_secret = (const void *)&server_key->payload.data[2];
 	ret = rxgk_set_up_token_cipher(server_secret, &token_enc, enctype, &krb5, GFP_NOFS);
 	up_read(&server_key->sem);
 	key_put(server_key);
 	if (ret < 0)
 		goto cant_get_token;

 	/* We can now decrypt and parse the token/ticket.  This allows us to
 	 * gain access to K0, from which we can derive the transport key and
 	 * thence decode the authenticator.
 	 */
 	ret = rxgk_decrypt_skb(krb5, token_enc, skb,
 			       &ticket_offset, &ticket_len, &ec);
 	crypto_free_aead(token_enc);
 	token_enc = NULL;
 	if (ret < 0) {
 		if (ret != -ENOMEM)
 			return rxrpc_abort_conn(conn, skb, ec, ret,
 						rxgk_abort_resp_tok_dec);
+		return ret;
 	}

 	ret = conn->security->default_decode_ticket(conn, skb, ticket_offset,
 						    ticket_len, _key);
 	if (ret < 0)
 		goto cant_get_token;

 	_leave(" = 0");
 	return ret;

 cant_get_server_key:
 	ret = PTR_ERR(server_key);
 	switch (ret) {
 	case -ENOMEM:
 		goto temporary_error;
 	case -ENOKEY:
 	case -EKEYREJECTED:
 	case -EKEYEXPIRED:
 	case -EKEYREVOKED:
 	case -EPERM:
 		return rxrpc_abort_conn(conn, skb, RXGK_BADKEYNO, -EKEYREJECTED,
 					rxgk_abort_resp_tok_nokey);
 	default:
 		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EKEYREJECTED,
 					rxgk_abort_resp_tok_keyerr);
 	}

 cant_get_token:
 	switch (ret) {
 	case -ENOMEM:
 		goto temporary_error;
 	case -EINVAL:
 		return rxrpc_abort_conn(conn, skb, RXGK_NOTAUTH, -EKEYREJECTED,
 					rxgk_abort_resp_tok_internal_error);
 	case -ENOPKG:
 		return rxrpc_abort_conn(conn, skb, KRB5_PROG_KEYTYPE_NOSUPP,
 					-EKEYREJECTED, rxgk_abort_resp_tok_nopkg);
 	}

 temporary_error:
 	/* Ignore the response packet if we got a temporary error such as
 	 * ENOMEM.  We just want to send the challenge again.  Note that we
 	 * also come out this way if the ticket decryption fails.
 	 */
 	return ret;

 short_packet:
 	return rxrpc_abort_conn(conn, skb, RXGK_PACKETSHORT, -EPROTO,
 				rxgk_abort_resp_tok_short);
 }
-- 


